def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the solid dividing line.
    for r in range(h):
        if len(set(grid[r])) == 1:
            sep = grid[r][0]
            top, bottom = grid[:r], grid[r + 1:]
            if not top or len(top) != len(bottom):
                continue
            common = ({v for row in top for v in row} &
                      {v for row in bottom for v in row}) - {sep}
            if common:
                color = min(common)
                return [
                    [3 if top[i][j] == color and bottom[i][j] == color else color
                     for j in range(w)]
                    for i in range(len(top))
                ]

    for c in range(w):
        if len({grid[i][c] for i in range(h)}) == 1:
            sep = grid[0][c]
            if c == 0 or w - c - 1 != c:
                continue
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            common = ({v for row in left for v in row} &
                      {v for row in right for v in row}) - {sep}
            if common:
                color = min(common)
                return [
                    [3 if left[i][j] == color and right[i][j] == color else color
                     for j in range(c)]
                    for i in range(h)
                ]

